from pathlib import Path
import re

ROOT = Path(".")
WORKFLOW = Path(".github/workflows/apply-pet-team-delivery-improvements.yml")
SELF = Path("scripts/apply-pet-team-delivery-improvements.py")

def read(path):
    return (ROOT / path).read_text()

def write(path, content):
    target = ROOT / path
    target.parent.mkdir(parents=True, exist_ok=True)
    target.write_text(content)

def replace_once(path, old, new):
    content = read(path)
    if old not in content:
        raise RuntimeError(f"Trecho nao encontrado em {path}: {old[:120]!r}")
    if content.count(old) != 1:
        raise RuntimeError(f"Trecho ambiguo em {path}: {content.count(old)} ocorrencias")
    write(path, content.replace(old, new, 1))

def regex_once(path, pattern, replacement, flags=0):
    content = read(path)
    updated, count = re.subn(pattern, replacement, content, count=1, flags=flags)
    if count != 1:
        raise RuntimeError(f"Regex nao encontrou trecho unico em {path}: {pattern[:120]!r}, count={count}")
    write(path, updated)

